import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:flutter_svg/svg.dart';import 'package:font_awesome_flutter/font_awesome_flutter.dart';import '../../../../Core/Utils/Extensions/context_extension.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../Config/Assets/image_svg.dart';import '../../../../Core/Resources/app_colors.dart';import 'filter_page.dart';class CustomSearchTextField extends StatefulWidget {  const CustomSearchTextField({super.key});  @override  State<CustomSearchTextField> createState() => _CustomSearchTextFieldState();}class _CustomSearchTextFieldState extends State<CustomSearchTextField> {  late TextEditingController search = TextEditingController();  @override  void initState() {    search = TextEditingController(text: "");    super.initState();  }  @override  Widget build(BuildContext context) {    return Hero(      tag: "Search",      child: Padding(        padding: const EdgeInsets.only(top: 35, bottom: 24).w,        child: TextFormField(          onChanged: (result) {            // SearchCubit.get(context).category = result;            // SearchCubit.get(context).search();          },          controller: search,          decoration: InputDecoration(            enabledBorder: buildOutlineInputBorder(),            focusedBorder: buildOutlineInputBorder(),            hintText: context.local.Search,            prefixIcon: IconButton(              onPressed: () {},              icon: Opacity(                opacity: .5,                child: IconButton(                  onPressed: () {                    // SearchCubit.get(context).search();                  },                  icon: FaIcon(FontAwesomeIcons.magnifyingGlass),                ),              ),            ),            suffixIcon: Padding(              padding:                  EdgeInsets.only(top: 17, bottom: 17, right: 16, left: 16),              child: Row(                mainAxisAlignment: MainAxisAlignment.end,                mainAxisSize: MainAxisSize.min,                children: [                  SvgPicture.asset(                    AppImagesSvg.vector,                    fit: BoxFit.contain,                    height: 18.w,                  ),                  8.horizontalSpace,                  InkWell(                    onTap: () {                      context.buildCustomBottomSheet(                          widget: FilterPage(), increaseHeight: true);                    },                    child: SvgPicture.asset(                      AppImagesSvg.filter,                      fit: BoxFit.contain,                      width: 26.w,                    ),                  ),                ],              ),            ),          ),        ),      ),    );  }  OutlineInputBorder buildOutlineInputBorder() {    return OutlineInputBorder(      borderSide: BorderSide(        color: AppColors.line,      ),      borderRadius: BorderRadius.circular(        24,      ).r,    );  }  void goSearch() {}  void goFilter() {}  void goBack() {}  void goScreen() {}}